pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(address actor, uint256 ts) public {
        vm.assume(actor != address(0));
        ts = bound(ts, 2, type(uint256).max / 2);

        vm.warp(ts);
        vm.deal(actor, 20 ether);

        // First call at time ts: must succeed.
        vm.prank(actor);
        c.fallback{value: 10 ether}();
        assertEq(c.pastBlockTime(), ts + 1);

        // Universal rule: a second call at the SAME timestamp must revert,
        // since block.timestamp is no longer > pastBlockTime.
        vm.prank(actor);
        bool ok;
        try c.fallback{value: 10 ether}() { ok = true; } catch { ok = false; }
        assertTrue(!ok, "same-timestamp repeat call must revert");
    }
}

