pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint64 blockNumber, uint64 ts, address actor) public {
        // admissible domain: any block number hitting a payout block, any fresh timestamp
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(blockNumber > 0 && blockNumber % 15 == 0);
        vm.assume(ts > 1); // strictly greater than pastBlockTime (initially 0; ts set before call)

        vm.roll(blockNumber);
        vm.warp(ts);

        uint256 callerBefore = actor.balance;
        uint256 contractBefore = address(c).balance; // 10 ether from setUp
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        require(ok, "call reverted");

        // Rule: on a payout block (block.number % 15 == 0) the caller receives
        // exactly c's entire pre-call balance; the mutant never pays out.
        assertTrue(actor.balance == callerBefore + contractBefore);
    }
}

