pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 ts) public {
        // keep first call admissible: timestamp must be > pastBlockTime (initially 0)
        vm.assume(ts > 0);
        ts = bound(ts, 1, type(uint256).max - 2);

        address actor = address(0xABCD);
        vm.deal(actor, 20 ether);

        // first call at time ts
        vm.warp(ts);
        vm.prank(actor);
        c.fallback{value: 10 ether}();

        // invariant: pastBlockTime == ts + 1, and at time ts + 1 the strict
        // guard (block.timestamp > pastBlockTime) fails -> the reference
        // reverts on any second call at ts + 1; the mutant (>=) accepts it.
        assertEq(c.pastBlockTime(), ts + 1);

        vm.warp(ts + 1);
        bool ok;
        vm.prank(actor);
        try c.fallback{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
        }

        // reference: second call at same-blocktime+1 always reverts
        assertTrue(!ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 t0, address actor1, address actor2) public {
        vm.assume(actor1 != address(0) && actor2 != address(0) && actor1 != address(c) && actor2 != address(c));
        t0 = bound(t0, 1, 2**64);

        // first accepted call at t0, at a block number NOT divisible by 15 (no payout)
        vm.warp(t0);
        if (block.number % 15 == 0) vm.roll(block.number + 1);
        vm.deal(actor1, 10 ether);
        vm.prank(actor1);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        require(ok1);

        // second call exactly at timestamp t0 + 1, at a block number divisible by 15 (payout on success)
        vm.warp(t0 + 1);
        uint256 n = block.number;
        vm.roll(n + (15 - (n % 15)));
        vm.deal(actor2, 10 ether);
        vm.prank(actor2);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        // Reference: second call reverts (timestamp not > pastBlockTime), balance untouched (20 ether).
        // Mutant: second call succeeds (>=), pays out everything, balance becomes 0.
        assertTrue(address(c).balance == 20 ether);
    }
}

